#include <vector>
using namespace std;

class DSU {
    vector<int> p;
public:
    DSU(int n) : p(n) {
        for (int i = 0; i < n; ++i) p[i] = i;
    }

    int find(int x) {
        return p[x] == x ? x : p[x] = find(p[x]);
    }

    void unite(int x, int y) {
        p[find(x)] = find(y);
    }

    void reset(int x, int val) {
        p[x] = val;
    }

    vector<int> get() { return p; }
};

class Solution {
public:
    bool check(int x, int y, vector<vector<int>>& restrictions, DSU& dsu) {
        for (auto& r : restrictions)
            if ((dsu.find(r[0]) == dsu.find(x) && dsu.find(r[1]) == dsu.find(y)) ||
                (dsu.find(r[0]) == dsu.find(y) && dsu.find(r[1]) == dsu.find(x)))
                return false;
        return true;
    }

    vector<bool> friendRequests(int n, vector<vector<int>>& restrictions, vector<vector<int>>& requests) {
        DSU dsu(n);
        vector<bool> res;
        for (auto& r : requests) {
            int x = dsu.find(r[0]), y = dsu.find(r[1]);
            if (x == y) {
                res.push_back(true);
                continue;
            }
            if (!check(x, y, restrictions, dsu)) {
                res.push_back(false);
                continue;
            }
            dsu.unite(x, y);
            res.push_back(true);
        }
        return res;
    }
};
